import React, { useRef } from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

interface CarouselProps {
  images: { src: string; alt?: string }[];
  speed?: number;
  textOverlay?: { content: React.ReactNode; positionClass?: string }[];
  classText?: string;
}

const Carousel: React.FC<CarouselProps> = ({
  images,
  speed = 2000,
  textOverlay = [],
  classText,
}) => {
  const sliderRef = useRef<Slider | null>(null);

  const settings = {
    dots: false,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: speed,
    pauseOnHover: false,
    arrows: false,
  };

  const handleMouseEnter = () => {
    if (sliderRef.current) {
      sliderRef.current.slickPause();
    }
  };
  const handleMouseLeave = () => {
    if (sliderRef.current) {
      sliderRef.current.slickPlay();
    }
  };

  return (
    <div
      className={styles.carouselContainer}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <Slider {...settings} ref={sliderRef}>
        {images.map((image, index) => (
          <div key={index} className="relative -mb-2">
            <img
              src={image.src}
              alt={image.alt || `Slide ${index + 1}`}
              className={styles.carouselImage}
            />
            <div className={styles.carouselOverlay} />
            {textOverlay[index]?.content && (
              <div
                className={`${styles.carouselText} ${
                  textOverlay[index].positionClass || ""
                } ${classText || ""}`}
              >
                {textOverlay[index].content}
              </div>
            )}
          </div>
        ))}
      </Slider>
    </div>
  );
};

export default Carousel;

const styles = {
  carouselContainer:
    "w-full mx-auto overflow-hidden relative z-10",
  carouselImage: "w-full object-cover",
  carouselText:
    "absolute w-full text-white sm:text-light text-xl sm:text-3xl text_shadow bottom-0 p-4 z-20",
    carouselOverlay: "absolute inset-0 bg-black bg-opacity-40 sm:bg-opacity-10 z-10",
}
